<template>
  <div class="full-width">
    <q-btn-group class="group-btn-panel" outline>
      <q-btn
        v-for="(button, btnIdx) in buttons"
        :key="btnIdx"
        class="cursor-pointer"
        :class="button.selected ? 'q-btn-selected' : ''"
        outline
        color="#9d9898"
        :label="$t(button.translation_key)"
        @click="
          toggleFieldsVisibility(button.fields, button.name, button.selected)
        "
      />
    </q-btn-group>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { GROUP_NAMES } from 'src/constants';
import { useFormBuilderStore } from 'src/store/main';
import { FORM_BUILDER_CONSTANTS } from 'src/formBuilder/formBuilderConstants';
import validationButtonPanelHelper from 'src/formBuilder/validationButtonPanelHelper';

export default defineComponent({
  name: 'CheckBox',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      buttons: {} as any,
    };
  },
  mixins: [validationButtonPanelHelper],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.addFieldsButtonsVibility();
  },

  methods: {
    toggleFieldsVisibility(fieldList: [], name: string, hidden: boolean) {
      if (this.isButtonToggleDisable()) {
        return;
      }

      this.buttons.forEach((button: any, index: any) => {
        if (button.name == name) {
          button.selected = !hidden;
        }
      });
      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          let field_name = subRow.field_name;
          if (fieldList.some((field) => field === field_name)) {
            subRow.visibile = !hidden;
            this.formBuilderConfigModel[field_name].visibile = !hidden;
          }
        }
      }
      this.prepareLayoutForTemplate();
      this.$forceUpdate();
    },

    addFieldsButtonsVibility() {
      this.addVibilityButtons();
      let buttons_visibility = this.checkButtonsVisibilty();
      let amountGroup1 = JSON.parse(
        JSON.stringify(FORM_BUILDER_CONSTANTS.amountGroup1),
      );
      let amountGroup2 = JSON.parse(
        JSON.stringify(FORM_BUILDER_CONSTANTS.amountGroup2),
      );
      let amountGroup3 = JSON.parse(
        JSON.stringify(FORM_BUILDER_CONSTANTS.amountGroup3),
      );

      let allButtonField: string[] = [];

      this.buttons.forEach((button: any, btnInx: any) => {
        let fieldList = Object.values(button.fields);

        for (const [index, field_name] of fieldList.entries()) {
          let field = field_name as string;
          if (!this.formBuilderConfigModel[field]) {
            continue;
          }
          allButtonField.push(field);

          if (buttons_visibility[button.name] === true) {
            button.selected = true;
            this.formBuilderConfigModel[field].visibile = true;
          } else {
            button.selected = false;
            this.formBuilderConfigModel[field].visibile = false;
          }

          if (this.formBuilderConfigModel[field].is_hidden) {
            if (amountGroup1.includes(field)) {
              amountGroup1 = amountGroup1.filter(
                (item: string) => item !== field,
              );
            } else if (amountGroup2.includes(field)) {
              amountGroup2 = amountGroup2.filter(
                (item: string) => item !== field,
              );
            } else if (amountGroup3.includes(field)) {
              amountGroup3 = amountGroup3.filter(
                (item: string) => item !== field,
              );
            }
          }
        }
      });

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          let field_name = subRow.field_name;
          if (group.name === GROUP_NAMES.tax_details) {
            if (allButtonField.some((field) => field === field_name)) {
              subRow.visibile =
                this.formBuilderConfigModel[field_name].visibile;

              if (amountGroup1.includes(subRow.field_name)) {
                subRow.elementWidth = Math.round(
                  this.calculateRowColSize(amountGroup1.length),
                );
              } else if (amountGroup2.includes(subRow.field_name)) {
                subRow.elementWidth = Math.round(
                  this.calculateRowColSize(amountGroup2.length),
                );
              } else if (amountGroup3.includes(subRow.field_name)) {
                subRow.elementWidth = Math.round(
                  this.calculateRowColSize(amountGroup3.length),
                );
              }
            }
          }
        }
      }

      this.prepareLayoutForTemplate();
    },

    addVibilityButtons() {
      this.buttons = [
        {
          selected: false,
          name: 'full',
          translation_key: 'full',
          fields: ['net_amount', 'tax_amount', 'tax_rate', 'tax_code'],
        },
        {
          selected: false,
          name: 'reduced',
          translation_key: 'reduced',
          fields: ['net_amount_2', 'tax_amount_2', 'tax_rate_2', 'tax_code_2'],
          alt_translation_keys: {
            net_amount_2: 'net_amount',
            tax_amount_2: 'tax_amount',
            tax_rate_2: 'tax_rate',
            tax_code_2: 'tax_code',
          },
        },
        {
          selected: false,
          name: 'free',
          translation_key: 'free',
          fields: ['net_amount_3', 'tax_amount_3', 'tax_rate_3', 'tax_code_3'],
          alt_translation_keys: {
            net_amount_3: 'net_amount',
            tax_amount_3: 'tax_amount',
            tax_rate_3: 'tax_rate',
            tax_code_3: 'tax_code',
          },
        },
      ];
    },

    checkButtonsVisibilty() {
      var buttons_visibility: { [k: string]: any } = {};
      this.buttons.forEach((button: any, btnInx: any) => {
        let fieldList = Object.values(button.fields);

        if (!buttons_visibility.hasOwnProperty(button.name)) {
          buttons_visibility[button.name] = false;
        }

        fieldList.forEach((field: any, btnInx: any) => {
          if (
            this.formBuilderModel[field] &&
            (this.formBuilderModel[field].value ||
              this.formBuilderModel[field].is_required ||
              this.formBuilderModel[field].color == 'error-border-left')
          ) {
            buttons_visibility[button.name] = true;
          }
        });
      });

      this.makeFullTaxDetailRowVisible(buttons_visibility);
      return buttons_visibility;
    },

    makeFullTaxDetailRowVisible(buttons: any) {
      let anyEnable = false;
      for (let [name, enable] of Object.entries(buttons)) {
        if (enable) {
          anyEnable = true;
        }
      }
      if (!anyEnable) {
        buttons['full'] = true;
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      formLayout,
    } = storeToRefs(form_builder_store);
    return {
      formBuilderConfigModel,
      isFormBuilderMode,
      formBuilderModel,
      formLayout,
    };
  },
});
</script>

<style scoped lang="scss">
.group-btn-panel {
  margin-top: 3px;
  float: right;
  color: rgb(76 65 65 / 87%);
}

.group-btn-panel .q-btn {
  padding: 0px;
  padding-left: 10px;
  padding-right: 10px;
  min-height: 1.9em;
  color: #9d9898 !important;
}
</style>
