<template>
  <div class="row items-center justify-center" v-if="isFormBuilderMode">
    {{ $t('qr_code_extracted_fields') }}
  </div>
  <div class="full-width" v-if="doc_loaded && hasQRInfo()">
    <div class="row">
      <div
        class="col-sm-6 secondary-c-text text-h6 q-pt-sm q-pb-sm text-weight-bold"
      >
        {{ $t('qr_code') }}
      </div>

      <!-- single fields -->
      <div :class="'row full-width '">
        <template
          v-for="(field_value, field_name) in record.qr_code_data"
          :key="field_name"
        >
          <div
            class="col-6 q-pt-sm qr-fields"
            v-if="field_value && typeof field_value !== 'object'"
          >
            <div class="row">
              {{ makeLabelFromFieldName(String(field_name)) }}
            </div>
            <div class="row">
              <q-input
                :data-field-name="field_name"
                outlined
                :disable="true"
                :class="
                  ' bg-disable input-field input-text-28px full-width ' +
                  field_name +
                  '_input '
                "
                :type="'text'"
                v-model="record.qr_code_data[field_name]"
              >
              </q-input>
            </div>
          </div>
        </template>
        <!-- END single fields -->
      </div>

      <div
        class="row link cursor-pointer font-size-14"
        v-if="!show_more"
        @click="show_more = true"
      >
        {{ $t('show_more') }}
      </div>
      <template v-if="show_more">
        <!-- Object fields loop -->
        <template
          v-for="(field_value, field_name) in record.qr_code_data"
          :key="field_name"
        >
          <template v-if="field_value && typeof field_value === 'object'">
            <div
              :class="
                'row full-width q-pt-sm pr-14 ' +
                field_name +
                (typeof field_value === 'object'
                  ? ' secondary-c-text text-weight-bold '
                  : '')
              "
            >
              {{ makeLabelFromFieldName(String(field_name)) }}
            </div>

            <div :class="'row full-width '">
              <template
                v-for="(sub_field_value, sub_field_name) in field_value"
                :key="sub_field_name"
              >
                <div class="col-6 q-mt-sm qr-fields" v-if="sub_field_value">
                  <div class="row">
                    {{ makeLabelFromFieldName(String(sub_field_name)) }}
                  </div>
                  <div class="row">
                    <q-input
                      :data-field-name="sub_field_name"
                      outlined
                      :disable="true"
                      :class="
                        ' bg-disable full-width input-field input-text-28px ' +
                        sub_field_name +
                        '_input '
                      "
                      :type="'text'"
                      v-model="record.qr_code_data[field_name][sub_field_name]"
                    >
                    </q-input>
                  </div>
                </div>
              </template>
            </div>
          </template>
          <!-- if only object -->
        </template>
        <!-- END object field loop -->

        <div
          class="row link cursor-pointer font-size-14"
          @click="show_more = false"
        >
          {{ $t('show_less') }}
        </div>
      </template>
      <!-- END show more -->
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';

export default defineComponent({
  name: 'QRCodeExtractedFields',
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        if (newVal) {
          this.load_view = true;
        }
      },
    },
  },
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: [
    'inputClicked',
    'inputValueChanges',
    'updateModel',
    'applyFuzzySearch',
    'markTableColumns',
    'itemAdded',
    'removeField',
  ],
  mixins: [displayFieldLabel],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  methods: {
    hasQRInfo() {
      return (
        !this.isFormBuilderMode &&
        this.doc_loaded &&
        this.record.hasOwnProperty('qr_code_data') &&
        this.record.qr_code_data != null
      );
    },

    makeLabelFromFieldName(field_name: string) {
      return field_name.replace(/_/g, ' ').toUpperCase();
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode } = storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { doc_loaded, record } = storeToRefs(doc_store);
    return {
      isFormBuilderMode,
      doc_loaded,
      record,
      load_view: ref(false),
      show_more: ref(false),
    };
  },
});
</script>
