<template>
  <div class="full-width">
    <q-btn-group class="group-btn-panel pr-14 mt-15" outline>
      <template v-for="(button, btnIdx) in buttons" :key="btnIdx">
        <q-btn
          :class="button.selected ? 'q-btn-selected' : ''"
          outline
          color="#9d9898"
          v-if="!button.is_hidden || isFormBuilderMode"
          @click="toggleGroupFieldsVisibility(button.field, button.selected)"
        >
          <q-icon :name="button.icon" size="md" />
          <q-tooltip>{{ button.label }}</q-tooltip>
        </q-btn>
      </template>
    </q-btn-group>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { GROUP_NAMES } from 'src/constants';
import { useFormBuilderStore } from 'src/store/main';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import { FORM_BUILDER_CONSTANTS } from 'src/formBuilder/formBuilderConstants';
import validationButtonPanelHelper from 'src/formBuilder/validationButtonPanelHelper';

export default defineComponent({
  name: 'CheckBox',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
  },
  data() {
    return {
      buttons: {} as any,
    };
  },
  mixins: [validationButtonPanelHelper, displayFieldLabel],

  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted: function () {
    this.addAdditionalAmountPanelInRows();
  },

  methods: {
    // ✅ NEW: Generate buttons dynamically from Layout Manager (Backend)
    generateButtonsFromLayout() {
      const buttons = [];

      // Find tax_details group from backend layout
      for (const group of this.formLayout) {
        if (group.name === GROUP_NAMES.tax_details) {
          for (const field of group.rows) {
            const fieldName = field.field_name;

            // Only create buttons for additional/negative amount fields
            if (fieldName && (
              fieldName.startsWith('additional_amount') ||
              fieldName.startsWith('negative_amount') ||
              fieldName === 'shipping_charges'
            )) {
              // Determine icon based on field name
              const isNegative = fieldName.startsWith('negative_amount');
              const icon = isNegative ? 'mdi:minus-circle-outline' : 'mdi:plus-circle-outline';

              buttons.push({
                selected: false,
                is_hidden: field.is_hidden || false,  // ✅ Trust Layout Manager
                name: fieldName,
                icon: icon,
                field: fieldName,
                label: this.displayFieldLabelFor(field) || field.label || fieldName,
              });
            }
          }
        }
      }

      return buttons;
    },

    addAdditionalAmountPanelInRows() {
      let aditionalAmountGroupPositive = JSON.parse(
        JSON.stringify(FORM_BUILDER_CONSTANTS.aditionalAmountGroupPositive),
      );
      let aditionalAmountGroupNegative = JSON.parse(
        JSON.stringify(FORM_BUILDER_CONSTANTS.aditionalAmountGroupNegative),
      );

      let allButtonField: string[] = [];
      let renderDefaultAmountField = true;

      // ✅ CHANGED: Generate buttons dynamically from Layout Manager
      this.buttons = this.generateButtonsFromLayout();

      let fieldToRemove = '';
      for (const [btnIndex, button] of this.buttons.entries()) {
        fieldToRemove = '';
        let fieldName = button.field;
        allButtonField.push(fieldName);

        if (this.formBuilderConfigModel[fieldName].isHidden) {
          // this.formBuilderConfigModel[fieldName].isHidden = true;
          button.is_hidden = true;
          fieldToRemove = fieldName;
        } else if (this.formBuilderModel[fieldName].value) {
          button.selected = true;
          this.formBuilderModel[fieldName].visibile = true;
          this.formBuilderConfigModel[fieldName].visibile = true;
          renderDefaultAmountField = false;
        } else {
          this.formBuilderConfigModel[fieldName].visibile = false;
          fieldToRemove = fieldName;
        }

        if (fieldToRemove) {
          if (aditionalAmountGroupPositive.includes(fieldName)) {
            aditionalAmountGroupPositive = aditionalAmountGroupPositive.filter(
              (item: string) => item !== fieldName,
            );
          } else if (aditionalAmountGroupNegative.includes(fieldName)) {
            aditionalAmountGroupNegative = aditionalAmountGroupNegative.filter(
              (item: string) => item !== fieldName,
            );
          }
        }
      }

      if (renderDefaultAmountField) {
        this.buttons[0].selected = true;
        this.formBuilderModel[this.buttons[0].field].visibile = true;
        this.formBuilderConfigModel[this.buttons[0].field].visibile = true;
      }

      for (const [index, group] of this.formLayout.entries()) {
        if (group.name === GROUP_NAMES.tax_details) {
          for (const [index2, subRow] of group.rows.entries()) {
            if (allButtonField.some((field) => field === subRow.field_name)) {
              subRow.visibile =
                this.formBuilderConfigModel[subRow.field_name].visibile;

              if (aditionalAmountGroupPositive.includes(subRow.field_name)) {
                subRow.elementWidth = Math.round(
                  this.calculateRowColSize(aditionalAmountGroupPositive.length),
                );
              } else if (
                aditionalAmountGroupNegative.includes(subRow.field_name)
              ) {
                subRow.elementWidth = Math.round(
                  this.calculateRowColSize(aditionalAmountGroupNegative.length),
                );
              }
            }
          }
        }
      }
    },

    toggleGroupFieldsVisibility(field_name: string, hidden: boolean) {
      if (this.isButtonToggleDisable()) {
        return;
      }

      this.buttons.forEach((button: any, index: any) => {
        if (button.field == field_name) {
          button.selected = !hidden;
        }
      });

      let aditionalAmountGroupPositive = [];
      let aditionalAmountGroupNegative = [];

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          if (group.name === GROUP_NAMES.tax_details) {
            if (subRow.field_name == field_name) {
              subRow.visibile = !hidden;
            }

            if (subRow.visibile && !subRow.is_hidden) {
              if (
                FORM_BUILDER_CONSTANTS.aditionalAmountGroupPositive.includes(
                  subRow.field_name,
                )
              ) {
                aditionalAmountGroupPositive.push(subRow.field_name);
              } else if (
                FORM_BUILDER_CONSTANTS.aditionalAmountGroupNegative.includes(
                  subRow.field_name,
                )
              ) {
                aditionalAmountGroupNegative.push(subRow.field_name);
              }
            }
          }
        }
      }

      for (const group of this.formLayout) {
        for (const subRow of group.rows) {
          if (group.name === GROUP_NAMES.tax_details) {
            if (aditionalAmountGroupPositive.includes(subRow.field_name)) {
              subRow.elementWidth = Math.round(
                this.calculateRowColSize(aditionalAmountGroupPositive.length),
              );
            } else if (
              aditionalAmountGroupNegative.includes(subRow.field_name)
            ) {
              subRow.elementWidth = Math.round(
                this.calculateRowColSize(aditionalAmountGroupNegative.length),
              );
            }
          }
        }
      }
      this.prepareLayoutForTemplate();
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,
      formLayout,
    } = storeToRefs(form_builder_store);
    return {
      formBuilderConfigModel,
      isFormBuilderMode,
      formBuilderModel,
      formLayout,
    };
  },
});
</script>

