<template>
  <f-btn
    :label="formBuilderConfigModel[fieldName].label"
    :disable="isReadOnly || record.extraction_method === 'ELECTRONIC_DOCUMENT'"
    class="full-width q-mt-sm"
    @click="clickEvent"
  />

  <q-dialog v-model="confirmRuleSave" persistent>
    <q-card>
      <q-card-section
        class="row"
        style="justify-content: center; display: flex"
      >
        <q-avatar icon="warning" color="primary" text-color="white" />
      </q-card-section>

      <q-card-section
        class="row items-center"
        style="justify-content: center; display: flex"
      >
        <span class="q-ml-sm">{{
          $t('SAVE_RULES_WARNING')
        }}</span>
      </q-card-section>

      <q-card-actions align="right">
        <f-btn appearance="cancel" :label="$t('cancel')" v-close-popup />
        <f-btn :label="$t('done')" v-close-popup @click="saveRules()" />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useFormBuilderStore,
  useDocumentStore,
  useDocLockStore,
} from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin';
import { aiTableApiService } from 'src/services';
import { ApiExceptions } from 'src/exceptions/index';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
    class: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [helperMixin],
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },

  methods: {
    clickEvent(event: any) {
      event.stopPropagation();
      if (this.isFormBuilderMode) {
        this.$emit('inputClicked', this.fieldName);
        return;
      }

      this.confirmRuleSave = true;
    },

    async saveRules() {
      try {
        this.showLoading();
        const actionLockAcquired = await this.hasActionAcquiredLock();
        if (!actionLockAcquired) {
          return;
        }
        this.confirmRuleSave = false;
  
        if (this.record.hasOwnProperty('table_data_copy')) {
          delete this.record['table_data_copy'];
        }
        
        const data = {
          data: JSON.stringify(this.record),
        } as dynamicObj;
        const response = await aiTableApiService.saveRules(data);
        if (response.success === false) {
          throw { message: response.message };
        }
        notify.success(this.$t('MSG_SAVE'));
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    const doc_lock_store = useDocLockStore();
    const { hasActionAcquiredLock } = doc_lock_store;
    return {
      formBuilderConfigModel,
      hasActionAcquiredLock,
      record,
      isFormBuilderMode,
      confirmRuleSave: ref(false),
    };
  },
});
</script>
