<template>
  <f-btn
    v-if="isButtonVisible"
    :label="formBuilderConfigModel[fieldName].label"
    class="full-width q-mt-sm"
    @click="clickEvent"
  >
    <q-icon
      v-if="isFormBuilderMode && !isModuleOn()"
      flat
      dense
      name="error"
      size="24px"
      color="white"
    >
      <q-tooltip class="bg-red" anchor="bottom right" self="top right">
        {{ $t('module_disabled') }}
      </q-tooltip>
    </q-icon>
  </f-btn>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useFormBuilderStore,
  useDocumentStore,
  useSettingStore,
} from 'src/store/main';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { auto_accounting_setting } from 'src/constants';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
    class: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [helperMixin],
  watch: {},
  data() {
    return {
      auto_accounting_setting,
    };
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  computed: {
    isButtonVisible: function () {
      if (this.isFormBuilderMode) {
        return true;
      }

      // parent component to handle visibility
      if (this.show_button_type === this.currentField.fieldType) {
        return true;
      } else if (this.show_button_type !== '') {
        return false;
      }

      //
      if (this.isModuleOn()) {
        return true;
      }
      return false;
    },
  },
  methods: {
    isModuleOn() {
      if (!this.user_settings[this.auto_accounting_setting]) {
        this.user_settings[this.auto_accounting_setting] = false;
      }
      return Boolean(this.user_settings[this.auto_accounting_setting]);
    },

    async clickEvent(event: any) {
      event.stopPropagation();
      if (this.isFormBuilderMode) {
        this.$emit('inputClicked', this.fieldName);
        return;
      }
      try {
        if (this.isReadOnly) {
          this.$router.push('/accounting/' + this.$route.params.id);
          return;
        }

        this.showLoading();
        this.record.po_multi_matched = [];
        const response: dynamicObj = await this.saveAndValidate();
        if (response.success === false) {
          const event = new CustomEvent('display_fields_errors', {});
          document.dispatchEvent(event);
          notify.error(response.message);
          return;
        }
        this.$router.push('/accounting/' + this.$route.params.id);
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { formBuilderModel, isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record, doctype, tb_version } = storeToRefs(doc_store);
    const { saveAndValidate } = doc_store;

    const settings_store = useSettingStore();
    const { user_settings, loading_settings } = storeToRefs(settings_store);
    return {
      saveAndValidate,
      doctype,
      record,
      formBuilderModel,
      isFormBuilderMode,
      formBuilderConfigModel,

      user_settings,
      loading_settings,
      show_button: ref(false),
    };
  },
});
</script>
