<template>
  <f-btn
    v-if="isButtonVisible"
    :label="formBuilderConfigModel[fieldName].label"
    class="full-width q-mt-sm"
    @click="clickEvent"
  >
  </f-btn>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import {
  useFormBuilderStore,
  useDocumentStore,
  useSettingStore,
  useDocLockStore,
} from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin.js';
import { notify } from 'src/components/notifications/notify';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
    class: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [helperMixin],
  watch: {},
  data() {
    return {};
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  computed: {
    isButtonVisible: function () {
      if (this.isFormBuilderMode) {
        return true;
      }

      // parent component to handle visibility
      if (this.show_button_type === this.currentField.fieldType) {
        return true;
      } else if (this.show_button_type !== '') {
        return false;
      }

      return true;
    },
  },
  methods: {
    async clickEvent(event: any) {
      event.stopPropagation();
      if (this.isFormBuilderMode) {
        this.$emit('inputClicked', this.fieldName);
        return;
      }
      try {
        if (this.isReadOnly) {
          return;
        }

        this.showLoading();
        const response = await this.rejectDocument(this.record.doc_id);
        if (response.success === false) {
          notify.error(response.message);
          return;
        }

        this.routeToDashboard();
      } catch (err) {
        logError(err);
      } finally {
        this.hideLoading();
      }
    },

    routeToDashboard() {
      window.removeEventListener('beforeunload', this.onTabClose);
      this.$router.push('/dashboard');
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);
    const { rejectDocument } = doc_store;

    const doc_lock_store = useDocLockStore();
    const { releaseDocLock } = doc_lock_store;

    return {
      releaseDocLock,
      rejectDocument,
      record,
      isFormBuilderMode,
      formBuilderConfigModel,
      show_button: ref(false),
    };
  },
});
</script>
