<template>
  <f-btn
    :label="formBuilderConfigModel[fieldName].label"
    :disable="isReadOnly"
    class="full-width q-mt-sm"
    @click="clickEvent"
  />
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent } from 'vue';
import { useFormBuilderStore, useDocumentStore } from 'src/store/main';
import helperMixin from 'src/mixins/helperMixin';

export default defineComponent({
  name: 'TextInput',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    show_button_type: {
      type: String,
      default: '',
    },
    class: {
      type: String,
      default: '',
    },
  },
  emits: ['inputClicked', 'updateModel'],
  mixins: [helperMixin],
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },

  methods: {
    clickEvent(event: any) {
      event.stopPropagation();
      if (this.isFormBuilderMode) {
        this.$emit('inputClicked', this.fieldName);
        return;
      }

      this.record['export_parameters'] = {
        doc_export_status: this.currentField.exportType,
        validate: false,
      };

      const custom_event = new CustomEvent('trigger_export', {});
      document.dispatchEvent(custom_event);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { isFormBuilderMode, formBuilderConfigModel } =
      storeToRefs(form_builder_store);

    const doc_store = useDocumentStore();
    const { record } = storeToRefs(doc_store);

    return {
      formBuilderConfigModel,
      record,
      isFormBuilderMode,
    };
  },
});
</script>
