<template>
  <div class="full-width">
    <q-icon v-if="isFormBuilderMode" flat dense name="error" size="24px">
      <q-tooltip class="bg-grey" anchor="bottom right" self="top right">
        <div class="q-pa-md">
          <div class="row items-center">
            <div class="col">Buttons visibility</div>
          </div>

          <div class="row">
            <div class="col">
              Auto Accounting = Cost Invoice + Auto Accounting module is on
            </div>
          </div>
          <div class="row">
            <div class="col">
              PO Match = Purchase Invoice + Table Exists + PO Enable
            </div>
          </div>

          <div class="row">
            <div class="col">Export = No Auto Accounting AND No PO Match</div>
          </div>
        </div>
      </q-tooltip>
    </q-icon>
  </div>
  <div class="full-width">
    <template
      v-for="(element, index) in formBuilderConfigModel[fieldName]
        .child_elements"
      :key="index"
    >
      <div
        v-bind="formBuilderConfigModel[element.name]"
        @click="inputClicked(element.name)"
        class="display-block element_parent cursor-move"
        :style="
          'width:' + getElementWidth(formBuilderConfigModel[element.name]) + '%'
        "
        :class="
          element.name == activeFieldName ? 'is--active  dashed-border' : ' '
        "
        v-if="
          isFormBuilderMode ||
          exclueded_buttons.indexOf(element.fieldType) !== -1 ||
          show_button_type === element.fieldType
        "
      >
        <component
          @inputClicked="inputClicked"
          :is="element.fieldType"
          :currentField="formBuilderConfigModel[element.name]"
          :fieldName="element.name"
          :show_button_type="show_button_type"
          :isReadOnly="isReadOnly"
          class="form__field"
        >
        </component>
      </div>
    </template>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import ExportButton from './FormElementButton.vue';
import poActionsUtil from 'src/utils/poActionsUtil';
import displayFieldLabel from 'src/utils/displayFieldLabel';
import PoMatchButton from './ButtonFormElements/PoMatch.vue';
import SaveRulesButton from './ButtonFormElements/SaveRules.vue';
import { auto_accounting_setting, CONSTANTS } from 'src/constants';
import formBuilderHelper from 'src/formBuilder/utils/formBuilderHelper';
import AutoAccountingButton from './ButtonFormElements/AutoAccounting.vue';
import { formBuilderInputTypes } from 'src/formBuilder/formBuilderConstants';
import {
  useFormBuilderStore,
  useDocumentStore,
  useSettingStore,
} from 'src/store/main';

export default defineComponent({
  name: 'InvoiceButtons',
  props: {
    currentField: {
      type: Object,
      default: new Object(),
    },
    fieldName: {
      type: String,
      default: '',
    },
    isReadOnly: {
      type: Boolean,
      default: false,
    },
    groupIndex: {
      type: Number,
      default: 0,
    },
    itemIndex: {
      type: Number,
      default: 0,
    },
  },
  emits: [
    'inputClicked',
    'inputValueChanges',
    'updateModel',
    'applyFuzzySearch',
    'markTableColumns',
    'itemAdded',
    'removeField',
  ],
  mixins: [displayFieldLabel, formBuilderHelper, poActionsUtil],
  components: {
    PoMatchButton,
    SaveRulesButton,
    ExportButton,
    AutoAccountingButton,
  },
  watch: {
    doc_loaded: {
      handler: function (newVal, oldVal) {
        this.init();
      },
    },
    loading_settings: {
      handler: function (newVal, oldVal) {
        // data loading is done and value never set
        if (newVal == true && oldVal == false) {
          return;
        }
        this.init();
      },
    },
  },
  data() {
    return {
      auto_accounting_setting,
    };
  },
  beforeMount: function () {
    if (this.isFormBuilderMode) {
      this.$emit('updateModel', this.currentField);
    }
  },
  mounted() {
    //  mout event listeners
    this.init();
    document.addEventListener('field_value_updated', this.fieldValueUpdated);
    document.addEventListener('prepare_rows', this.reInitButtons);
    document.addEventListener('delete_table', this.reInitButtons);
  },
  unmounted: function () {
    //  unmout event listeners
    document.removeEventListener('field_value_updated', this.fieldValueUpdated);
    document.removeEventListener('prepare_rows', this.reInitButtons);
    document.removeEventListener('delete_table', this.reInitButtons);
  },
  methods: {
    inputClicked(fieldName: string) {
      const event = new CustomEvent('element_click', {
        detail: fieldName,
      });
      document.dispatchEvent(event);
    },

    fieldValueUpdated(e: any) {
      if (e.detail.field_name === CONSTANTS.invoice_sub_type) {
        this.init();
      }
    },

    async init() {
      if (this.isFormBuilderMode) {
        return;
      }

      let on_button = formBuilderInputTypes.EXPORT_BUTTON;

      if (this.isCostInvoice()) {
        this.record.po_multi_matched = [];
        on_button = formBuilderInputTypes.AUTO_ACCOUNTING_BUTTON;
      } else if (
        (await this.isPoSettingActivate(this.doctype)) &&
        this.hasTable() &&
        ((this.formBuilderModel.invoice_sub_type &&
          this.formBuilderModel.invoice_sub_type.formatted_value ===
            CONSTANTS.purchase_invoice) ||
          (this.formBuilderModel.invoice_sub_type_us_cad &&
            this.formBuilderModel.invoice_sub_type_us_cad.formatted_value ===
              'Trade Invoice'))
      ) {
        on_button = formBuilderInputTypes.PO_MATCH_BUTTON;
      }

      this.show_button_type = on_button;
    },

    reInitButtons() {
      if (!this.hasTable()) {
        this.init();
      }
    },

    isCostInvoice() {
      if (
        Boolean(this.user_settings[this.auto_accounting_setting]) === true &&
        ((this.formBuilderModel.invoice_sub_type &&
          this.formBuilderModel.invoice_sub_type.formatted_value ===
            'Cost Invoice') ||
          (this.formBuilderModel.invoice_sub_type_us_cad &&
            this.formBuilderModel.invoice_sub_type_us_cad.formatted_value ===
              'Expense Invoice'))
      ) {
        return true;
      }
      return false;
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const {
      formBuilderModel,
      formBuilderConfigModel,
      documentTableNames,
      isFormBuilderMode,
      activeFieldName,
      documentTables,
      docType,
    } = storeToRefs(form_builder_store);

    const { getElementWidth } = form_builder_store;

    const doc_store = useDocumentStore();
    const { record, doctype, doc_loaded } = storeToRefs(doc_store);
    const { hasTable } = doc_store;

    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);

    return {
      hasTable,
      user_settings,
      record,
      doctype,
      getElementWidth,
      docType,
      doc_loaded,
      documentTables,
      activeFieldName,
      formBuilderModel,
      isFormBuilderMode,
      documentTableNames,
      formBuilderConfigModel,
      show_button_type: ref(formBuilderInputTypes.EXPORT_BUTTON),
      exclueded_buttons: ref([formBuilderInputTypes.SAVE_RULES_BUTTON]),
    };
  },
});
</script>

<style lang="scss" scoped>
.element_parent:nth-child(odd) {
  padding-right: 8px;
}
</style>
